/**
 * Unit tests for @ohos/dsh-tool-user-profile.
 *
 * The pure functions carry the design risk: a parse bug loses the user's
 * facts, and a splice bug destroys their own prose around the block. Both are
 * tested against realistic bodies (prose above and below the block, a
 * hand-edited block, a half-written block from a crash).
 */
import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtemp, readFile, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

import {
	applyEdit,
	formatFact,
	parseFacts,
	profilePath,
	renderBlock,
	spliceBlock,
} from "../index.js";

const BEGIN = "<!-- dsh:user-profile:begin -->";
const END = "<!-- dsh:user-profile:end -->";

// ---------------------------------------------------------------- parseFacts

test("parseFacts returns nothing for a body without a block", () => {
	assert.deepEqual(parseFacts(""), []);
	assert.deepEqual(parseFacts("# my own notes\n\nsome prose\n"), []);
});

test("parseFacts reads dated entries in file order", () => {
	const body = renderBlock([
		{ date: "2026-11-01", text: "prefers Chinese answers" },
		{ date: "2026-11-20", text: "dislikes filler openers" },
	]);
	const facts = parseFacts(body);
	assert.equal(facts.length, 2);
	assert.equal(facts[0].date, "2026-11-01");
	assert.equal(facts[0].text, "prefers Chinese answers");
	assert.equal(facts[1].date, "2026-11-20");
});

test("parseFacts keeps a hand-written undated entry", () => {
	const body = `${BEGIN}\n- no date here\n${END}\n`;
	assert.deepEqual(parseFacts(body), [{ date: "", text: "no date here" }]);
});

test("parseFacts treats an unterminated block as empty", () => {
	const body = `# prose\n${BEGIN}\n- 2026-11-20 — lost\n`;
	assert.deepEqual(parseFacts(body), []);
});

test("parseFacts ignores prose between the markers", () => {
	const body = `${BEGIN}\n\n## heading\n\n- 2026-11-20 — real fact\n\n${END}\n`;
	assert.deepEqual(parseFacts(body), [{ date: "2026-11-20", text: "real fact" }]);
});

test("parseFacts does not read a block twice when markers repeat", () => {
	const one = renderBlock([{ date: "2026-11-20", text: "a" }]);
	const body = `${one}${one}`;
	assert.deepEqual(parseFacts(body).map((f) => f.text), ["a"]);
});

// ---------------------------------------------------------------- renderBlock

test("renderBlock states the empty case instead of an empty range", () => {
	const block = renderBlock([]);
	assert.ok(block.includes("Nothing recorded yet"));
	assert.ok(block.startsWith(BEGIN));
	assert.ok(block.trimEnd().endsWith(END));
});

test("renderBlock output round-trips through parseFacts", () => {
	const facts = [
		{ date: "2026-10-01", text: "uses HarmonyOS tablets for review" },
		{ date: "2026-11-20", text: "wants conclusions before evidence" },
	];
	assert.deepEqual(parseFacts(renderBlock(facts)), facts);
});

test("formatFact keeps a supplied date and dates an undated entry today", () => {
	assert.equal(formatFact({ date: "2026-01-02", text: "x" }), "- 2026-01-02 — x");
	const today = new Date().toISOString().slice(0, 10);
	assert.equal(formatFact({ date: "", text: "x" }), `- ${today} — x`);
});

// ---------------------------------------------------------------- spliceBlock

test("spliceBlock appends a block after the user's prose", () => {
	const body = "# My instructions\n\nBe brief.\n";
	const block = renderBlock([{ date: "2026-11-20", text: "prefers Chinese" }]);
	const next = spliceBlock(body, block);
	assert.ok(next.startsWith("# My instructions"));
	assert.ok(next.includes("Be brief."));
	assert.ok(next.includes("prefers Chinese"));
	assert.ok(next.indexOf("Be brief.") < next.indexOf(BEGIN));
});

test("spliceBlock replaces only the managed range, keeping prose on both sides", () => {
	const old = `# above\n\ntext above\n\n${renderBlock([{ date: "2026-01-01", text: "old fact" }])}\ntext below\n`;
	const next = spliceBlock(old, renderBlock([{ date: "2026-11-20", text: "new fact" }]));
	assert.ok(next.includes("text above"));
	assert.ok(next.includes("text below"));
	assert.ok(!next.includes("old fact"));
	assert.ok(next.includes("new fact"));
	// Prose below stays below the new block.
	assert.ok(next.indexOf(END) < next.indexOf("text below"));
});

test("spliceBlock repairs a half-written block by replacing to EOF", () => {
	const body = `# above\n${BEGIN}\n- 2026-01-01 — half\n`;
	const block = renderBlock([{ date: "2026-11-20", text: "recovered" }]);
	const next = spliceBlock(body, block);
	assert.ok(next.startsWith("# above"));
	assert.ok(!next.includes("half"));
	assert.ok(next.includes("recovered"));
	assert.equal((next.match(new RegExp(BEGIN, "g")) ?? []).length, 1);
});

test("spliceBlock on an empty body writes just the block", () => {
	const body = "";
	const next = spliceBlock(body, renderBlock([]));
	assert.equal(next, renderBlock([]));
});

// ---------------------------------------------------------------- applyEdit

const base = [{ date: "2026-11-01", text: "prefers Chinese answers" }];

test("applyEdit add appends one dated fact", () => {
	const { facts, note } = applyEdit(base, { action: "add", text: "dislikes emoji", date: "2026-11-20" });
	assert.equal(facts.length, 2);
	assert.equal(facts[1].text, "dislikes emoji");
	assert.equal(facts[1].date, "2026-11-20");
	assert.match(note, /recorded/);
});

test("applyEdit add is a no-op for an identical fact", () => {
	const { facts, note } = applyEdit(base, { action: "add", text: "prefers Chinese answers" });
	assert.equal(facts.length, 1);
	assert.match(note, /already recorded/);
});

test("applyEdit replace supersedes by substring and re-dates", () => {
	const { facts } = applyEdit(base, {
		action: "replace",
		match: "Chinese answers",
		text: "now wants English answers",
		date: "2026-11-20",
	});
	assert.equal(facts.length, 1);
	assert.equal(facts[0].text, "now wants English answers");
	assert.equal(facts[0].date, "2026-11-20");
});

test("applyEdit replace reports a miss instead of appending", () => {
	const { facts, note } = applyEdit(base, { action: "replace", match: "nope", text: "x" });
	assert.deepEqual(facts, base);
	assert.match(note, /no entry/);
});

test("applyEdit forget drops every matching entry", () => {
	const start = [
		{ date: "2026-11-01", text: "likes tabs" },
		{ date: "2026-11-02", text: "likes tabs in SQL" },
		{ date: "2026-11-03", text: "dislikes semicolons" },
	];
	const { facts, note } = applyEdit(start, { action: "forget", match: "likes tabs" });
	assert.deepEqual(facts.map((f) => f.text), ["dislikes semicolons"]);
	assert.match(note, /forgot 2 entries/);
});

test("applyEdit forget reports a miss", () => {
	const { facts, note } = applyEdit(base, { action: "forget", match: "absent" });
	assert.equal(facts.length, 1);
	assert.match(note, /no entry/);
});

test("applyEdit drops the oldest entries at the fact cap", () => {
	const many = Array.from({ length: 80 }, (_, i) => ({ date: "2026-01-01", text: `f${i}` }));
	const { facts, note } = applyEdit(many, { action: "add", text: "newest" });
	assert.equal(facts.length, 80);
	assert.equal(facts[79].text, "newest");
	assert.equal(facts[0].text, "f1");
	assert.match(note, /dropped 1 oldest entry/);
});

test("applyEdit rejects an unknown action", () => {
	assert.throws(() => applyEdit(base, { action: "nuke" }), /unknown action/);
});

test("applyEdit add without a date stamps today", () => {
	const today = new Date().toISOString().slice(0, 10);
	const { facts } = applyEdit([], { action: "add", text: "x" });
	assert.equal(facts[0].date, today);
});

// ---------------------------------------------------------------- profilePath

test("profilePath accepts a relative name inside the home", () => {
	assert.equal(profilePath("/data/home", "AGENTS.md"), "/data/home/AGENTS.md");
	assert.equal(profilePath("/data/home", "notes/USER.md"), "/data/home/notes/USER.md");
});

test("profilePath refuses an escape", () => {
	assert.throws(() => profilePath("/data/home", "../evil.md"), /stay inside the harness home/);
	assert.throws(() => profilePath("/data/home", "/etc/passwd"), /must be relative/);
});

// ---------------------------------------------------------------- end to end

test("a full add → read cycle survives on disk", async () => {
	const home = await mkdtemp(join(tmpdir(), "profile-test-"));
	const target = profilePath(home, "AGENTS.md");
	// User prose already present.
	await writeFile(target, "# Keep this\n\nMy own instruction.\n", "utf8");

	const edit = applyEdit(parseFacts(await readFile(target, "utf8")), {
		action: "add",
		text: "prefers conclusions first",
		date: "2026-11-20",
	});
	await writeFile(target, spliceBlock(await readFile(target, "utf8"), renderBlock(edit.facts)), "utf8");

	const body = await readFile(target, "utf8");
	const facts = parseFacts(body);
	assert.deepEqual(facts, [{ date: "2026-11-20", text: "prefers conclusions first" }]);
	assert.ok(body.includes("My own instruction."), "user prose must survive the write");
});

test("two successive edits keep exactly one block", async () => {
	const home = await mkdtemp(join(tmpdir(), "profile-test-"));
	const target = profilePath(home, "AGENTS.md");
	let body = "";
	for (const text of ["first", "second", "third"]) {
		const edit = applyEdit(parseFacts(body), { action: "add", text, date: "2026-11-20" });
		body = spliceBlock(body, renderBlock(edit.facts));
	}
	assert.equal((body.match(new RegExp(BEGIN, "g")) ?? []).length, 1);
	assert.equal((body.match(new RegExp(END, "g")) ?? []).length, 1);
	assert.deepEqual(parseFacts(body).map((f) => f.text), ["first", "second", "third"]);
});